import React, { useState, useEffect } from 'react';
import { useLanguage } from '../contexts/LanguageContext';
import scoringService from '../services/scoringService';
import { loadUserSquad } from '../services/squadService';
import { useAuth } from '../contexts/AuthContext';
import './ScoringDisplay.css';

const ScoringDisplay = ({ match, onClose }) => {
  const { language } = useLanguage();
  const { currentUser } = useAuth();
  const [scoring, setScoring] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (match && currentUser) {
      calculateScoring();
    }
  }, [match, currentUser]);

  const calculateScoring = async () => {
    try {
      setLoading(true);
      setError(null);

      // Load user's saved squad for this match
      const userSquad = await loadUserSquad(currentUser.uid, match.id);
      
      if (!userSquad) {
        setError(language === 'ar' ? 'لم يتم العثور على تشكيلة محفوظة' : 'No saved squad found');
        setLoading(false);
        return;
      }

      // Use demo scoring for Al-Ittifaq match
      let scoringResult;
      
      if (match.opponent && match.opponent.toLowerCase().includes('ittifaq')) {
        // Demo scoring for Al-Ittifaq match
        scoringResult = scoringService.getAlIttifaqDemoScoring(
          userSquad,
          userSquad.formation
        );
      } else {
        // For other matches, use regular calculation
        const mockActualSquad = {
          players: {
            '1': true,   // Bono (GK)
            '4': true,   // Koulibaly (CB)
            '5': true,   // Ali Albulaihy (CB)
            '6': true,   // Renan Lodi (LB)
            '7': true,   // Theo (RB)
            '8': true,   // Neves (CM)
            '9': true,   // Malcom (RW)
            '10': true,  // Nunez (LW)
            '11': true,  // Mitrovic (ST)
            '12': true,  // Savic (CM)
            '24': true   // Kaio Cesar (ST)
          }
        };

        const matchResult = scoringService.determineMatchResult(match);
        const actualFormation = '4-3-3';
        
        // Extract player IDs from user squad (position-based structure)
        const userPlayerIds = [];
        Object.values(userSquad.players || {}).forEach(player => {
          if (player && player.id) {
            userPlayerIds.push(String(player.id));
          }
        });

        // Convert to the format expected by calculatePoints
        const userSquadForScoring = {
          players: {}
        };
        userPlayerIds.forEach(playerId => {
          userSquadForScoring.players[playerId] = true;
        });

        scoringResult = await scoringService.calculatePoints(
          userSquadForScoring,
          mockActualSquad,
          matchResult,
          userSquad.formation,
          actualFormation,
          match.id
        );
      }

      setScoring(scoringResult);
    } catch (error) {
      console.error('Error calculating scoring:', error);
      setError(language === 'ar' ? 'خطأ في حساب النقاط' : 'Error calculating points');
    } finally {
      setLoading(false);
    }
  };

  const getMatchResultText = (result) => {
    if (language === 'ar') {
      switch (result) {
        case 'win': return 'فوز';
        case 'loss': return 'خسارة';
        case 'draw': return 'تعادل';
        default: return 'غير معروف';
      }
    } else {
      switch (result) {
        case 'win': return 'Win';
        case 'loss': return 'Loss';
        case 'draw': return 'Draw';
        default: return 'Unknown';
      }
    }
  };

  const getMatchResultColor = (result) => {
    switch (result) {
      case 'win': return '#00c851';
      case 'loss': return '#ff4444';
      case 'draw': return '#ff8800';
      default: return '#666';
    }
  };

  if (loading) {
    return (
      <div className="scoring-display">
        <div className="scoring-loading">
          <div className="loading-spinner"></div>
          <p>{language === 'ar' ? 'جاري حساب النقاط...' : 'Calculating points...'}</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="scoring-display">
        <div className="scoring-error">
          <div className="error-icon">⚠️</div>
          <p>{error}</p>
          <button onClick={onClose} className="close-btn">
            {language === 'ar' ? 'إغلاق' : 'Close'}
          </button>
        </div>
      </div>
    );
  }

  if (!scoring) {
    return (
      <div className="scoring-display">
        <div className="scoring-error">
          <p>{language === 'ar' ? 'لا توجد بيانات نقاط' : 'No scoring data available'}</p>
          <button onClick={onClose} className="close-btn">
            {language === 'ar' ? 'إغلاق' : 'Close'}
          </button>
        </div>
      </div>
    );
  }

  const explanations = scoringService.getScoringExplanation(scoring, language);
  const matchResult = scoringService.determineMatchResult(match);

  return (
    <div className="scoring-display">
      <div className="scoring-header">
        <h3>
          {language === 'ar' ? 'نتائج النقاط' : 'Scoring Results'}
        </h3>
        <button onClick={onClose} className="close-btn">×</button>
      </div>

      <div className="match-info">
        <div className="match-title">
          {language === 'ar' ? 'مباراة الهلال ضد' : 'Al-Hilal vs'} {match.opponent}
        </div>
        <div className="match-result" style={{ color: getMatchResultColor(matchResult) }}>
          {getMatchResultText(matchResult)}
        </div>
        {match.score && (
          <div className="match-score">
            {match.score.home} - {match.score.away}
          </div>
        )}
      </div>

      <div className="scoring-breakdown">
        <div className="scoring-item">
          <div className="scoring-label">
            {language === 'ar' ? 'اللاعبون المتطابقون' : 'Matching Players'}
          </div>
          <div className="scoring-value">
            {scoring.playerPoints} {language === 'ar' ? 'نقطة' : 'pts'}
          </div>
        </div>

        <div className="scoring-item">
          <div className="scoring-label">
            {language === 'ar' ? 'التشكيلة' : 'Formation'}
          </div>
          <div className="scoring-value">
            {scoring.formationPoints} {language === 'ar' ? 'نقطة' : 'pts'}
            {scoring.breakdown.formationMatch && (
              <span className="bonus-badge">
                {language === 'ar' ? 'تطابق كامل' : 'Exact Match'}
              </span>
            )}
            {scoring.breakdown.formationSimilar && (
              <span className="bonus-badge similar">
                {language === 'ar' ? 'تشابه' : 'Similar'}
              </span>
            )}
          </div>
        </div>

        {(matchResult === 'loss' || matchResult === 'draw') && (
          <div className="scoring-item">
            <div className="scoring-label">
              {language === 'ar' ? 'مقابل المجتمع' : 'Vs Community'}
            </div>
            <div className="scoring-value">
              {scoring.communityPoints} {language === 'ar' ? 'نقطة' : 'pts'}
            </div>
          </div>
        )}

        <div className="scoring-total">
          <div className="total-label">
            {language === 'ar' ? 'المجموع الكلي' : 'Total Points'}
          </div>
          <div className="total-value">
            {scoring.totalPoints} {language === 'ar' ? 'نقطة' : 'pts'}
          </div>
        </div>
      </div>

      <div className="scoring-details">
        <h4>{language === 'ar' ? 'التفاصيل' : 'Details'}</h4>
        <div className="details-list">
          <div className="detail-item">
            <span className="detail-label">
              {language === 'ar' ? 'اللاعبون المتطابقون:' : 'Matched Players:'}
            </span>
            <span className="detail-value">
              {scoring.breakdown.matchedPlayers.length}/11
            </span>
          </div>
          
          {scoring.breakdown.communityMatches.length > 0 && (
            <div className="detail-item">
              <span className="detail-label">
                {language === 'ar' ? 'مطابقة المجتمع:' : 'Community Matches:'}
              </span>
              <span className="detail-value">
                {scoring.breakdown.communityMatches.length}
              </span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ScoringDisplay;
