import React from 'react';
import { useLanguage } from '../contexts/LanguageContext';
import './SquadCopyModal.css';

const SquadCopyModal = ({ 
  isOpen, 
  onClose, 
  recentSquads, 
  onSelectSquad, 
  loading = false 
}) => {
  const { language } = useLanguage();

  if (!isOpen) return null;

  const formatDate = (dateString) => {
    if (!dateString) return '';
    const date = new Date(dateString);
    return date.toLocaleDateString(language === 'ar' ? 'ar-SA' : 'en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric'
    });
  };

  const getFormationDisplay = (formation) => {
    const formations = {
      '4-3-3': language === 'ar' ? '4-3-3 هجومي' : '4-3-3 Attacking',
      '4-4-2': language === 'ar' ? '4-4-2 متوازن' : '4-4-2 Balanced',
      '3-5-2': language === 'ar' ? '3-5-2 لعب الأجنحة' : '3-5-2 Wing Play',
      '4-2-3-1': language === 'ar' ? '4-2-3-1 سيطرة' : '4-2-3-1 Control',
      '3-4-3': language === 'ar' ? '3-4-3 عدواني' : '3-4-3 Aggressive',
      '5-3-2': language === 'ar' ? '5-3-2 دفاعي' : '5-3-2 Defensive'
    };
    return formations[formation] || formation;
  };

  const getPlayerCount = (players) => {
    return Object.keys(players || {}).length;
  };

  return (
    <div className="squad-copy-modal-overlay">
      <div className="squad-copy-modal">
        <div className="squad-copy-modal-header">
          <h3>{language === 'ar' ? 'نسخ من تشكيلة سابقة' : 'Copy from Previous Squad'}</h3>
          <button 
            className="squad-copy-modal-close"
            onClick={onClose}
            aria-label={language === 'ar' ? 'إغلاق' : 'Close'}
          >
            ×
          </button>
        </div>
        
        <div className="squad-copy-modal-content">
          {loading ? (
            <div className="squad-copy-loading">
              <div className="loading-spinner"></div>
              <p>{language === 'ar' ? 'جاري تحميل التشكيلات...' : 'Loading squads...'}</p>
            </div>
          ) : recentSquads.length === 0 ? (
            <div className="squad-copy-empty">
              <div className="empty-icon">📋</div>
              <p>{language === 'ar' ? 'لا توجد تشكيلات سابقة' : 'No previous squads found'}</p>
              <p className="empty-subtitle">
                {language === 'ar' 
                  ? 'قم ببناء وحفظ تشكيلة أولاً لاستخدام هذه الميزة' 
                  : 'Build and save a squad first to use this feature'
                }
              </p>
            </div>
          ) : (
            <div className="squad-copy-list">
              {recentSquads.map((squad) => (
                <div 
                  key={squad.id}
                  className="squad-copy-item"
                  onClick={() => onSelectSquad(squad)}
                >
                  <div className="squad-copy-info">
                    <div className="squad-copy-opponent">
                      {language === 'ar' ? 'ضد' : 'vs'} {squad.opponent}
                    </div>
                    <div className="squad-copy-details">
                      <span className="squad-competition">{squad.competition}</span>
                      <span className="squad-date">{formatDate(squad.date)}</span>
                    </div>
                    <div className="squad-copy-formation">
                      {getFormationDisplay(squad.formation)}
                    </div>
                  </div>
                  <div className="squad-copy-stats">
                    <div className="squad-players-count">
                      {getPlayerCount(squad.players)}/11 {language === 'ar' ? 'لاعب' : 'players'}
                    </div>
                    <div className="squad-bench-count">
                      {squad.bench?.length || 0}/12 {language === 'ar' ? 'بديل' : 'bench'}
                    </div>
                  </div>
                  <div className="squad-copy-action">
                    <button className="copy-squad-btn">
                      {language === 'ar' ? 'نسخ' : 'Copy'}
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
        
        <div className="squad-copy-modal-footer">
          <button 
            className="btn btn-secondary"
            onClick={onClose}
          >
            {language === 'ar' ? 'إلغاء' : 'Cancel'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default SquadCopyModal;
