/**
 * Avatar Extractor Utility
 * 
 * This utility helps extract avatar data from Firestore for deployment
 * Run this in the browser console to get avatar data
 */

import { collection, getDocs, doc, getDoc } from 'firebase/firestore';
import { db } from '../firebase/config';

/**
 * Extract all avatar data from Firestore
 * Run this in browser console to get avatar data for deployment
 */
export const extractAllAvatars = async () => {
  try {
    console.log('🔄 Extracting avatar data from Firestore...');
    
    const usersRef = collection(db, 'users');
    const usersSnap = await getDocs(usersRef);
    
    const avatarData = [];
    
    usersSnap.forEach((userDoc) => {
      const userData = userDoc.data();
      const userId = userDoc.id;
      
      if (userData.avatarBase64 && userData.avatarFileName) {
        avatarData.push({
          userId,
          fileName: userData.avatarFileName,
          mimeType: userData.avatarMimeType,
          base64Data: userData.avatarBase64
        });
      }
    });
    
    console.log(`📊 Found ${avatarData.length} avatars`);
    
    // Create download links for each avatar
    avatarData.forEach((avatar, index) => {
      const link = document.createElement('a');
      link.href = avatar.base64Data;
      link.download = avatar.fileName;
      link.textContent = `Download ${avatar.fileName}`;
      link.style.display = 'block';
      link.style.margin = '5px 0';
      link.style.padding = '5px';
      link.style.border = '1px solid #ccc';
      link.style.borderRadius = '3px';
      link.style.textDecoration = 'none';
      link.style.color = '#0066cc';
      
      document.body.appendChild(link);
    });
    
    console.log('✅ Avatar extraction complete! Download links created below.');
    return avatarData;
    
  } catch (error) {
    console.error('❌ Error extracting avatars:', error);
    return [];
  }
};

/**
 * Get avatar data for a specific user
 */
export const extractUserAvatar = async (userId) => {
  try {
    const userRef = doc(db, 'users', userId);
    const userSnap = await getDoc(userRef);
    
    if (userSnap.exists()) {
      const userData = userSnap.data();
      
      if (userData.avatarBase64 && userData.avatarFileName) {
        console.log(`📸 Avatar data for user ${userId}:`);
        console.log(`   - Filename: ${userData.avatarFileName}`);
        console.log(`   - MIME Type: ${userData.avatarMimeType}`);
        console.log(`   - Base64 Length: ${userData.avatarBase64.length}`);
        
        // Create download link
        const link = document.createElement('a');
        link.href = userData.avatarBase64;
        link.download = userData.avatarFileName;
        link.textContent = `Download ${userData.avatarFileName}`;
        link.style.display = 'block';
        link.style.margin = '10px 0';
        link.style.padding = '10px';
        link.style.border = '2px solid #0066cc';
        link.style.borderRadius = '5px';
        link.style.textDecoration = 'none';
        link.style.color = '#0066cc';
        link.style.fontWeight = 'bold';
        
        document.body.appendChild(link);
        
        return {
          fileName: userData.avatarFileName,
          mimeType: userData.avatarMimeType,
          base64Data: userData.avatarBase64
        };
      } else {
        console.log(`❌ No avatar data found for user ${userId}`);
        return null;
      }
    } else {
      console.log(`❌ User ${userId} not found`);
      return null;
    }
  } catch (error) {
    console.error('❌ Error extracting user avatar:', error);
    return null;
  }
};

// Make functions available globally for console use
if (typeof window !== 'undefined') {
  window.extractAllAvatars = extractAllAvatars;
  window.extractUserAvatar = extractUserAvatar;
  
  console.log('🛠️ Avatar extraction tools available:');
  console.log('   - extractAllAvatars() - Extract all avatars');
  console.log('   - extractUserAvatar(userId) - Extract specific user avatar');
}
