import { useState, useEffect } from 'react';
import userPointsService from '../services/userPointsService';

/**
 * Hook to get user's total points
 * @param {string} userId - User ID
 * @returns {Object} User points data and loading state
 */
export const useUserPoints = (userId) => {
  const [pointsData, setPointsData] = useState({
    totalPoints: 0,
    matchesPlayed: 0,
    averagePoints: 0,
    breakdown: {
      playerPoints: 0,
      formationPoints: 0,
      communityPoints: 0
    },
    recentMatches: []
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!userId) {
      setLoading(false);
      return;
    }

    const fetchUserPoints = async () => {
      try {
        setLoading(true);
        setError(null);
        
        const data = await userPointsService.calculateUserTotalPoints(userId);
        setPointsData(data);
      } catch (err) {
        console.error('Error fetching user points:', err);
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchUserPoints();
  }, [userId]);

  const refreshPoints = async () => {
    if (!userId) return;
    
    try {
      setLoading(true);
      userPointsService.clearUserCache(userId);
      const data = await userPointsService.calculateUserTotalPoints(userId);
      setPointsData(data);
    } catch (err) {
      console.error('Error refreshing user points:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return {
    ...pointsData,
    loading,
    error,
    refreshPoints
  };
};

export default useUserPoints;
