import { db } from '../firebase/config';
import { doc, setDoc, getDoc, getDocs, collection } from 'firebase/firestore';
import { getCountFromServer } from 'firebase/firestore';

// Save a squad for a specific user and match
export async function saveUserSquad(userId, matchId, squadData) {
  if (!userId || !matchId) throw new Error('Missing userId or matchId');
  const ref = doc(db, 'users', userId, 'squads', String(matchId));
  await setDoc(ref, squadData, { merge: true });
}

// Load a single squad for a user and match
export async function loadUserSquad(userId, matchId) {
  if (!userId || !matchId) throw new Error('Missing userId or matchId');
  const ref = doc(db, 'users', userId, 'squads', String(matchId));
  const snap = await getDoc(ref);
  return snap.exists() ? snap.data() : null;
}

// Fetch existence flags for multiple matches (returns map of matchId -> true)
export async function getUserSavedSquadFlags(userId, matchIds) {
  if (!userId || !Array.isArray(matchIds) || matchIds.length === 0) return {};
  // Firestore has no batch existence check by IDs without querying; fetch all user's squads and map
  const colRef = collection(db, 'users', userId, 'squads');
  const snapshot = await getDocs(colRef);
  const existing = {};
  snapshot.forEach((docSnap) => {
    const id = docSnap.id;
    if (matchIds.includes(id) || matchIds.includes(Number(id))) existing[id] = true;
  });
  return existing;
}


// COMMUNITY VOTES (one vote per user per match)

// Record a user's vote for a match if not already recorded
export async function recordUserCommunityVote(userId, matchId) {
  if (!userId || !matchId) throw new Error('Missing userId or matchId');
  const voteDoc = doc(db, 'communityVotes', String(matchId), 'voters', userId);
  const snap = await getDoc(voteDoc);
  if (!snap.exists()) {
    await setDoc(voteDoc, { votedAt: new Date().toISOString() });
  }
}

// Check if a user already voted for a match
export async function hasUserVoted(userId, matchId) {
  if (!userId || !matchId) return false;
  const voteDoc = doc(db, 'communityVotes', String(matchId), 'voters', userId);
  const snap = await getDoc(voteDoc);
  return snap.exists();
}

// Get total vote count for a match
export async function getCommunityVoteCount(matchId) {
  if (!matchId) return 0;
  const votersCol = collection(db, 'communityVotes', String(matchId), 'voters');
  const countSnap = await getCountFromServer(votersCol);
  return countSnap.data().count || 0;
}

// Get user's recent squads for copying
export async function getUserRecentSquads(userId, limit = 5) {
  if (!userId) return [];
  
  try {
    const squadsCol = collection(db, 'users', userId, 'squads');
    const squadsSnapshot = await getDocs(squadsCol);
    
    const squads = [];
    squadsSnapshot.forEach((doc) => {
      const data = doc.data();
      squads.push({
        id: doc.id,
        matchId: doc.id,
        opponent: data.opponent,
        competition: data.competition,
        date: data.date,
        formation: data.formation,
        players: data.players || {},
        bench: data.bench || [],
        savedAt: data.savedAt
      });
    });
    
    // Sort by savedAt date (most recent first)
    squads.sort((a, b) => new Date(b.savedAt) - new Date(a.savedAt));
    
    return squads.slice(0, limit);
  } catch (error) {
    console.error('Error getting recent squads:', error);
    return [];
  }
}

// Get community squad with vote percentages
export async function getCommunitySquad(matchId) {
  if (!matchId) return { squad: {}, percentages: {}, totalVotes: 0 };
  
  try {
    console.log('🔍 Getting community squad for matchId:', matchId);
    
    // First, get all users who voted for this match from communityVotes
    const votersCol = collection(db, 'communityVotes', String(matchId), 'voters');
    const votersSnapshot = await getDocs(votersCol);
    
    console.log('🗳️ Found', votersSnapshot.docs.length, 'voters for this match');
    
    if (votersSnapshot.docs.length === 0) {
      console.log('❌ No voters found for this match');
      return { squad: {}, percentages: {}, totalVotes: 0 };
    }
    
    // Now get the squad data for each voter
    const allSquads = [];
    
    for (const voterDoc of votersSnapshot.docs) {
      const userId = voterDoc.id;
      console.log('👤 Getting squad for voter:', userId);
      
      const squadDoc = doc(db, 'users', userId, 'squads', String(matchId));
      const squadSnap = await getDoc(squadDoc);
      
      if (squadSnap.exists()) {
        const squadData = squadSnap.data();
        console.log('✅ Found squad for user', userId, ':', squadData);
        if (squadData.players) {
          allSquads.push(squadData);
        }
      } else {
        console.log('❌ No squad found for user', userId);
      }
    }
    
    console.log('📈 Total squads found:', allSquads.length);
    
    if (allSquads.length === 0) {
      return { squad: {}, percentages: {}, totalVotes: 0 };
    }
    
    // Aggregate votes by position
    const positionVotes = {};
    const totalVotes = allSquads.length;
    
    console.log('🗳️ Aggregating votes from', totalVotes, 'squads');
    
    allSquads.forEach((squad, index) => {
      console.log(`📋 Squad ${index + 1}:`, squad.players);
      Object.entries(squad.players || {}).forEach(([position, player]) => {
        if (player && player.id) {
          if (!positionVotes[position]) {
            positionVotes[position] = {};
          }
          if (!positionVotes[position][player.id]) {
            positionVotes[position][player.id] = {
              player: player,
              votes: 0
            };
          }
          positionVotes[position][player.id].votes++;
          console.log(`✅ Vote for ${player.name} in ${position}`);
        }
      });
    });
    
    console.log('📊 Position votes:', positionVotes);
    
    // Find most popular player for each position
    const communitySquad = {};
    const percentages = {};
    
    Object.entries(positionVotes).forEach(([position, players]) => {
      const sortedPlayers = Object.values(players).sort((a, b) => b.votes - a.votes);
      if (sortedPlayers.length > 0) {
        const mostPopular = sortedPlayers[0];
        communitySquad[position] = mostPopular.player;
        percentages[position] = {
          percentage: Math.round((mostPopular.votes / totalVotes) * 100),
          votes: mostPopular.votes,
          totalVotes: totalVotes
        };
      }
    });
    
    const result = {
      squad: communitySquad,
      percentages: percentages,
      totalVotes: totalVotes
    };
    
    console.log('🏆 Final community squad result:', result);
    return result;
    
  } catch (error) {
    console.error('Error getting community squad:', error);
    return { squad: {}, percentages: {}, totalVotes: 0 };
  }
}


