import React, { useState } from 'react';
import { BrowserRouter, HashRouter, Routes, Route } from 'react-router-dom';
import { AuthProvider } from './contexts/AuthContext';
import * as LanguageCtx from './contexts/LanguageContext';
import { NotificationProvider } from './contexts/NotificationContext';
import LoginPage from './pages/LoginPage';
import MainLayout from './components/MainLayout';
import ProtectedRoute from './components/ProtectedRoute';
import SchedulePage from './pages/SchedulePage';
import DashboardPage from './pages/DashboardPage';
import PlayersPage from './pages/PlayersPage';
import AccountPage from './pages/AccountPage';
import PrizesPage from './pages/PrizesPage';
import './App.css';
import SplashScreen from './components/SplashScreen';
import './utils/avatarExtractor'; // Import avatar extraction utilities

function App() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [showSplash, setShowSplash] = useState(true);

  // Debug which providers/components are loaded
  try {
    // eslint-disable-next-line no-console
    console.log('Boot check:', {
      LanguageModuleKeys: Object.keys(LanguageCtx || {}),
      LanguageProvider: typeof LanguageCtx.LanguageProvider,
      AuthProvider: typeof AuthProvider,
      NotificationProvider: typeof NotificationProvider,
      MainLayout: typeof MainLayout,
      ProtectedRoute: typeof ProtectedRoute,
      SplashScreen: typeof SplashScreen,
      LoginPage: typeof LoginPage
    });
  } catch (e) {}

  const renderContent = () => {
    switch (activeTab) {
      case 'schedule':
        return <SchedulePage />;
      case 'dashboard':
        return <DashboardPage />;
      case 'players':
        return <PlayersPage />;
      case 'prizes':
        return <PrizesPage />;
      case 'account':
        return <AccountPage />;
      default:
        return <DashboardPage />;
    }
  };

  const LanguageProvider = LanguageCtx.LanguageProvider;
  const providersOk = LanguageProvider && AuthProvider && NotificationProvider;
  if (!providersOk) {
    console.error('One or more providers failed to load', {
      LanguageProvider,
      AuthProvider,
      NotificationProvider
    });
    return (
      <div style={{ padding: 24, fontFamily: 'sans-serif' }}>
        <h2>App initialization error</h2>
        <p>One or more providers failed to load. Please hard refresh (Ctrl+Shift+R). If the problem persists, check import/export of contexts.</p>
      </div>
    );
  }

  return (
    <LanguageProvider>
      <AuthProvider>
        <NotificationProvider>
        {(() => {
          const Router = process.env.NODE_ENV === 'production' ? HashRouter : BrowserRouter;
          return (
        <Router>
          <div className="App">
            {showSplash && <SplashScreen onDone={() => setShowSplash(false)} />}
            <Routes>
              <Route path="/login" element={<LoginPage />} />
              <Route 
                path="/" 
                element={
                  <ProtectedRoute>
                    <MainLayout activeTab={activeTab} onTabChange={setActiveTab}>
                      {renderContent()}
                    </MainLayout>
                  </ProtectedRoute>
                } 
              />
            </Routes>
          </div>
        </Router>
          );
        })()}
        </NotificationProvider>
      </AuthProvider>
    </LanguageProvider>
  );
}

export default App;
