/**
 * User Points Service
 * Calculates total points for a user across all their saved squads
 */

import { getUserRecentSquads } from './squadService';
import scoringService from './scoringService';

class UserPointsService {
  constructor() {
    this.pointsCache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  /**
   * Calculate total points for a user
   * @param {string} userId - User ID
   * @returns {Promise<Object>} Total points and breakdown
   */
  async calculateUserTotalPoints(userId) {
    if (!userId) {
      return {
        totalPoints: 0,
        matchesPlayed: 0,
        averagePoints: 0,
        breakdown: {
          playerPoints: 0,
          formationPoints: 0,
          communityPoints: 0
        },
        recentMatches: []
      };
    }

    try {
      // Check cache first
      const cacheKey = `user_${userId}`;
      const cached = this.pointsCache.get(cacheKey);
      if (cached && Date.now() - cached.timestamp < this.cacheTimeout) {
        return cached.data;
      }

      // Get all user's saved squads
      const userSquads = await getUserRecentSquads(userId, 50); // Get last 50 squads
      
      let totalPoints = 0;
      let totalPlayerPoints = 0;
      let totalFormationPoints = 0;
      let totalCommunityPoints = 0;
      let matchesPlayed = 0;
      const recentMatches = [];

      // Calculate points for each squad
      for (const squad of userSquads) {
        // Only calculate for completed matches (those with scores)
        if (squad.opponent && squad.date) {
          // Only calculate points for Al-Ittifaq match for now
          if (squad.opponent.toLowerCase().includes('ittifaq') || 
              squad.opponent.toLowerCase().includes('اتفاق')) {
            
            // Calculate points for this match
            const matchScoring = scoringService.getAlIttifaqDemoScoring(
              squad,
              squad.formation || '4-3-3'
            );

            totalPoints += matchScoring.totalPoints;
            totalPlayerPoints += matchScoring.playerPoints;
            totalFormationPoints += matchScoring.formationPoints;
            totalCommunityPoints += matchScoring.communityPoints;
            matchesPlayed++;

            // Add to recent matches
            recentMatches.push({
              matchId: squad.matchId,
              opponent: squad.opponent,
              date: squad.date,
              points: matchScoring.totalPoints,
              breakdown: matchScoring
            });
          }
        }
      }

      const result = {
        totalPoints,
        matchesPlayed,
        averagePoints: matchesPlayed > 0 ? Math.round(totalPoints / matchesPlayed) : 0,
        breakdown: {
          playerPoints: totalPlayerPoints,
          formationPoints: totalFormationPoints,
          communityPoints: totalCommunityPoints
        },
        recentMatches: recentMatches.slice(0, 5) // Last 5 matches
      };

      // Cache the result
      this.pointsCache.set(cacheKey, {
        data: result,
        timestamp: Date.now()
      });

      console.log('🔍 User points calculation:', {
        totalPoints: result.totalPoints,
        matchesPlayed: result.matchesPlayed,
        averagePoints: result.averagePoints
      });

      return result;
    } catch (error) {
      console.error('Error calculating user total points:', error);
      return {
        totalPoints: 0,
        matchesPlayed: 0,
        averagePoints: 0,
        breakdown: {
          playerPoints: 0,
          formationPoints: 0,
          communityPoints: 0
        },
        recentMatches: []
      };
    }
  }

  /**
   * Get points for a specific match
   * @param {string} userId - User ID
   * @param {string} matchId - Match ID
   * @returns {Promise<Object>} Points for the match
   */
  async getMatchPoints(userId, matchId) {
    try {
      const userSquads = await getUserRecentSquads(userId, 50);
      const squad = userSquads.find(s => s.matchId === matchId);
      
      if (!squad) {
        return { totalPoints: 0, breakdown: {} };
      }

      return scoringService.getAlIttifaqDemoScoring(
        squad,
        squad.formation || '4-3-3'
      );
    } catch (error) {
      console.error('Error getting match points:', error);
      return { totalPoints: 0, breakdown: {} };
    }
  }

  /**
   * Clear cache for a user
   * @param {string} userId - User ID
   */
  clearUserCache(userId) {
    const cacheKey = `user_${userId}`;
    this.pointsCache.delete(cacheKey);
  }

  /**
   * Clear all cache
   */
  clearAllCache() {
    this.pointsCache.clear();
  }
}

// Export singleton instance
export default new UserPointsService();
