import { doc, setDoc, getDoc } from 'firebase/firestore';
import { db } from '../firebase/config';

/**
 * Convert file to base64 string
 * @param {File} file - The file to convert
 * @returns {Promise<string>} Base64 string
 */
export const convertFileToBase64 = (file) => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result);
    reader.onerror = error => reject(error);
  });
};

/**
 * Save user avatar and update Firestore
 * @param {string} userId - User ID
 * @param {File} file - Avatar file
 * @returns {Promise<string>} Avatar URL
 */
export const saveUserAvatar = async (userId, file) => {
  if (!userId || !file) {
    throw new Error('Missing userId or file');
  }

  try {
    // Convert file to base64
    const base64String = await convertFileToBase64(file);
    
    // Create avatar filename
    const fileExtension = file.name.split('.').pop() || 'jpg';
    const avatarFileName = `${userId}.${fileExtension}`;
    
    // Save to Firestore with base64 data
    const userRef = doc(db, 'users', userId);
    await setDoc(userRef, { 
      photoURL: `/avatars/${avatarFileName}`,
      avatarBase64: base64String,
      avatarFileName: avatarFileName,
      avatarMimeType: file.type,
      lastUpdated: new Date().toISOString()
    }, { merge: true });

    // Log the avatar info for debugging
    console.log('📸 Avatar saved to Firestore:');
    console.log(`   - User ID: ${userId}`);
    console.log(`   - Filename: ${avatarFileName}`);
    console.log(`   - Base64 length: ${base64String.length} characters`);
    
    // Return the base64 data URL for immediate display
    return base64String;
  } catch (error) {
    console.error('Error saving avatar:', error);
    throw error;
  }
};

/**
 * Load user profile with avatar
 * @param {string} userId - User ID
 * @returns {Promise<Object|null>} User profile
 */
export const loadUserProfile = async (userId) => {
  if (!userId) return null;
  
  try {
    const userRef = doc(db, 'users', userId);
    const userSnap = await getDoc(userRef);
    
    if (userSnap.exists()) {
      const data = userSnap.data();
      
      // If we have base64 data, use it directly
      if (data.avatarBase64) {
        return {
          ...data,
          photoURL: data.avatarBase64 // Use base64 data directly
        };
      }
      
      // Otherwise, use the stored photoURL or default
      return {
        ...data,
        photoURL: data.photoURL || '/images/user-avatar.png'
      };
    }
    return null;
  } catch (error) {
    console.error('Error loading user profile:', error);
    return null;
  }
};

/**
 * Save user profile data
 * @param {string} userId - User ID
 * @param {Object} profileData - Profile data to save
 */
export const saveUserProfile = async (userId, profileData) => {
  if (!userId) return;
  
  try {
    const userRef = doc(db, 'users', userId);
    await setDoc(userRef, {
      ...profileData,
      lastUpdated: new Date().toISOString()
    }, { merge: true });
  } catch (error) {
    console.error('Error saving user profile:', error);
    throw error;
  }
};

/**
 * Get default avatar URL
 * @returns {string} Default avatar path
 */
export const getDefaultAvatar = () => {
  return '/images/user-avatar.png';
};

/**
 * Check if avatar exists locally
 * @param {string} avatarPath - Avatar path
 * @returns {boolean} Whether avatar exists
 */
export const avatarExists = (avatarPath) => {
  // For now, we'll assume it exists if it's not the default
  return avatarPath && avatarPath !== '/images/user-avatar.png';
};
