import React from 'react';
import { useLanguage } from '../contexts/LanguageContext';

const AutoFillButtons = ({ 
  canAutoFill, 
  onAutoFill,
  onCopySquad,
  canCopySquad = true
}) => {
  const { language } = useLanguage();

  return (
    <div className="auto-fill-section">
      <div className="auto-fill-buttons-container">
        <button 
          className="auto-fill-btn"
          onClick={onAutoFill}
          disabled={!canAutoFill}
        >
          <span>
            {language === 'ar' ? 'ملء تلقائي للتشكيلة' : 'Auto Fill Squad'}
          </span>
        </button>
        <button 
          id="copy-squad-button"
          className="copy-squad-btn"
          onClick={onCopySquad}
          disabled={!canCopySquad}
        >
          <span>
            {language === 'ar' ? 'نسخ من تشكيلة سابقة' : 'Copy from Previous'}
          </span>
        </button>
      </div>
    </div>
  );
};

export default AutoFillButtons;